def A(id, tr, la, en, group, region, summary, origin, course, branches, supply, clinical=(), related=(), models=(), aliases=(), sections=(), extra=()):
    facts = [("Köken", origin), ("Seyir", course)]
    if branches:
        facts.append(("Dalları", branches))
    facts.append(("Beslediği alan", supply))
    facts += list(extra)
    return E(id, tr, la, en, group, region, summary, facts=facts, sections=sections, clinical=clinical, related=related, models=models, aliases=aliases)


